# Retrieval-by-Outcome demo: outcome index mined from usage evidence.
OUTCOMES={"quiet room":[("acoustic-panels",0.92,12),("white-noise-machine",0.71,30),("earplugs",0.65,50)],
           "passing test suite":[("coverage-tool",0.88,20),("mutation-tester",0.81,8)]}
def by_outcome(outcome,budget=None):
    cands=OUTCOMES.get(outcome,[])
    if budget is not None: cands=[c for c in cands if c[2]<=budget]
    return sorted(cands,key=lambda c:-c[1])
for name,rate,ev in by_outcome("quiet room",budget=40):
    print("%s success=%.2f evidence=%d cost=%d"%(name,rate,ev,ev))

